INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES', 'SCIE.G4.FORCE_.HEAT.HEAT_SOURCES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'skill', 'essential', 'Grade 3 Environmental Activities introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'ENVI.G3.NATURA.HEAT.HEAT_SOURCES', 'skill', 'essential', 'Grade 3 Environmental Activities introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'ENVI.G3.SOCIAL.OUR_COMMUNITY.SAFE_PLACES', 'skill', 'essential', 'Keeping safe in the community (Grade 3) is the habit this skill applies to heat. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS.M_PL_NOT_ALIVE', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'Thinks plants are not alive because they do not walk or move about.', '{"question":"Why do we say a maize plant is a living thing?","wrong_answer":"It moves from place to place","correct_answer":"It grows, makes seeds, and responds to its surroundings"}'::jsonb, 'The child links being alive with moving the whole body.', 'Offer "It moves from place to place" next to the right answer and ask the question again in a new context.', 'Plant a bean seed in a cup and look at it every day: it grows and bends to the window without walking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS.M_PL_NO_WASTE', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'Thinks plants make no waste, only animals do.', '{"question":"Which of these do living things do? Does a plant remove waste?","wrong_answer":"No, only animals remove waste","correct_answer":"Yes, plants also get rid of waste"}'::jsonb, 'The child links waste with toilets and droppings.', 'Offer "No, only animals remove waste" next to the right answer and ask the question again in a new context.', 'Say that plants lose water vapour and gases through their leaves and drop old leaves and fruits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS.M_PL_NO_RESPOND', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'Thinks plants do not respond to changes around them.', '{"question":"A seedling on a window sill bends towards the light. What does this show?","wrong_answer":"The plant is not alive, it is only leaning","correct_answer":"The plant responds to light"}'::jsonb, 'The child thinks only animals react to things.', 'Offer "The plant is not alive, it is only leaning" next to the right answer and ask the question again in a new context.', 'Turn the cup around and watch the seedling bend back over two days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS.M_PP_LEAVES_ABSORB', 'SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS', 'Thinks the leaves take in water from the soil, or that roots make the plant''s food.', '{"question":"Which part of a plant takes in water from the soil?","wrong_answer":"The leaves","correct_answer":"The roots"}'::jsonb, 'The child mixes up where water enters and where food is made.', 'Offer "The leaves" next to the right answer and ask the question again in a new context.', 'Put a bean plant in coloured water and see which part first turns colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS.M_PP_STEM_ONLY_HOLDS', 'SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS', 'Thinks the stem only holds the plant up.', '{"question":"What does the stem do for a plant?","wrong_answer":"It only holds the plant up","correct_answer":"It holds the plant up and carries water and food"}'::jsonb, 'The child sees only the stem''s shape and strength.', 'Offer "It only holds the plant up" next to the right answer and ask the question again in a new context.', 'Stand a stem of a white flower in coloured water and see the colour climb up the stem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS.M_PP_LEAVES_SHADE_ONLY', 'SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS', 'Thinks leaves are only for shade or to look green, not to make food.', '{"question":"What do the leaves of a maize plant do?","wrong_answer":"They give shade only","correct_answer":"They make food for the plant using sunlight"}'::jsonb, 'The child has seen leaves as decoration or shelter.', 'Offer "They give shade only" next to the right answer and ask the question again in a new context.', 'Cover one leaf with dark paper for a week and look at how it fades.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS.M_PL_SEED_DEAD', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'Thinks a dry seed is dead, because it does not grow, feed or move while it is in a tin.', '{"question":"A bean seed has been kept dry in a tin for two months. Is it living?","wrong_answer":"No, it is dead because it does nothing","correct_answer":"Yes, it is alive but resting; planted in wet soil it grows"}'::jsonb, 'Uses "doing something now" as the test of life and does not know a seed can rest.', 'Offer "No, it is dead because it does nothing" next to the right answer and ask the question again in a new context.', 'Plant some of the tin beans in wet soil and watch them sprout within a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS.M_PP_FOOD_FROM_SOIL', 'SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS', 'Thinks plants get their food from the soil through the roots, like eating.', '{"question":"Where does a maize plant get its food from?","wrong_answer":"From the soil, through its roots","correct_answer":"It makes its own food in the leaves using sunlight"}'::jsonb, 'Compares a plant with an animal that eats; roots look like mouths in the soil.', 'Offer "From the soil, through its roots" next to the right answer and ask the question again in a new context.', 'Grow two seedlings, one in the dark: same soil, but the one without light turns yellow and weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS.M_AN_REPRODUCE_BIRTH_ONLY', 'SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS', 'Thinks animals reproduce only by giving birth to live young (not by eggs).', '{"question":"How do birds and fish reproduce?","wrong_answer":"They give birth to live young like a cow","correct_answer":"They lay eggs"}'::jsonb, 'The child has met the cow and the goat at home and not the egg.', 'Offer "They give birth to live young like a cow" next to the right answer and ask the question again in a new context.', 'List animals that lay eggs (hen, fish, frog, snake) and animals that give birth (cow, goat, dog).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS.M_AN_STILL_NOT_ALIVE', 'SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS', 'Thinks an animal that lies still or sleeps is not alive.', '{"question":"A lizard lies still in the sun. Is it alive?","wrong_answer":"No, it is not moving","correct_answer":"Yes, it is only resting and is still breathing"}'::jsonb, 'The child links being alive with moving all the time.', 'Offer "No, it is not moving" next to the right answer and ask the question again in a new context.', 'Watch a sleeping cat: its sides move as it breathes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS.M_AN_INSECT_NOT_ANIMAL', 'SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS', 'Thinks insects, worms and fish are not animals (only cows, goats, lions and other big animals are).', '{"question":"Is a butterfly an animal?","wrong_answer":"No, only big animals are animals","correct_answer":"Yes, it is an animal"}'::jsonb, 'The child uses "animal" to mean the big mammals.', 'Offer "No, only big animals are animals" next to the right answer and ask the question again in a new context.', 'List every living thing in the school compound that is not a plant: ants, birds, worms are animals too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT.M_VS_NO_LEGS_INVERT', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT', 'Thinks an animal with no legs (snake, fish) has no backbone.', '{"question":"Is a snake a vertebrate or an invertebrate?","wrong_answer":"An invertebrate, it has no legs","correct_answer":"A vertebrate, it has a backbone"}'::jsonb, 'The child looks at legs and not at the backbone.', 'Offer "An invertebrate, it has no legs" next to the right answer and ask the question again in a new context.', 'Feel your own backbone, then show a picture of a snake skeleton with its many small bones in a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT.M_VS_LEGS_VERTEBRATE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT', 'Thinks every animal with legs is a vertebrate (spider, ant, grasshopper, crab).', '{"question":"Is a grasshopper a vertebrate or an invertebrate?","wrong_answer":"A vertebrate, it has legs","correct_answer":"An invertebrate, it has no backbone"}'::jsonb, 'The child links legs with bones.', 'Offer "A vertebrate, it has legs" next to the right answer and ask the question again in a new context.', 'Look at a dead grasshopper: legs, but the body is soft inside a hard cover and there is no backbone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT.M_VS_SHELL_IS_BONE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT', 'Thinks a hard shell or hard cover (snail, crab, beetle) is a backbone.', '{"question":"Is a snail a vertebrate or an invertebrate?","wrong_answer":"A vertebrate, it has a hard shell","correct_answer":"An invertebrate, the shell is not a backbone"}'::jsonb, 'The child treats anything hard as bone.', 'Offer "A vertebrate, it has a hard shell" next to the right answer and ask the question again in a new context.', 'Note that a shell is on the outside and a backbone is inside the body along the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE.M_VR_SMALL_INVERT', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE', 'Thinks small animals are invertebrates and big ones are vertebrates (a chick, a mouse or a small frog taken as invertebrates).', '{"question":"Why is a small frog a vertebrate?","wrong_answer":"It is not, because it is small","correct_answer":"It has a backbone"}'::jsonb, 'The child uses size as the rule.', 'Offer "It is not, because it is small" next to the right answer and ask the question again in a new context.', 'Compare a large earthworm and a tiny chick: the small chick has a backbone and the long worm has none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE.M_VR_WINGS_OR_LEGS_RULE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE', 'Uses wings or the number of legs as the rule for vertebrates.', '{"question":"Which rule tells us an animal is an invertebrate?","wrong_answer":"It has more than four legs","correct_answer":"It has no backbone"}'::jsonb, 'The child picks a visible feature that is not the rule.', 'Offer "It has more than four legs" next to the right answer and ask the question again in a new context.', 'Sort pictures only by the backbone and ignore legs, wings and size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE.M_VR_WATER_RULE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE', 'Thinks all animals that live in water are vertebrates, or that all animals on land are.', '{"question":"Is a crab, which lives in water, a vertebrate?","wrong_answer":"Yes, because it lives in water like fish","correct_answer":"No, it has no backbone"}'::jsonb, 'The child sorts by where animals live.', 'Offer "Yes, because it lives in water like fish" next to the right answer and ask the question again in a new context.', 'Find crabs, snails and jellyfish among water animals that are invertebrates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS.M_AN_PLANTS_ARE_ANIMALS_MOVE', 'SCIE.G4.LIVING.ANIMALS.ANIMAL_LIFE_CHARS', 'Thinks anything that moves by itself is an animal, so a car or a river is alive.', '{"question":"A river moves all day. Is it a living thing?","wrong_answer":"Yes, because it moves","correct_answer":"No: it does not feed, grow, breathe or reproduce"}'::jsonb, 'Uses movement as the only sign of life.', 'Offer "Yes, because it moves" next to the right answer and ask the question again in a new context.', 'Go through the signs one by one for the river: it fails all but movement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT.M_VS_BIRD_NOT_VERTEBRATE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT', 'Thinks birds are not vertebrates because they are light and have feathers, not bones like a cow.', '{"question":"Is a hen a vertebrate or an invertebrate?","wrong_answer":"An invertebrate, it is light with feathers","correct_answer":"A vertebrate: it has a backbone"}'::jsonb, 'Has only felt the backbone of big animals and thinks feathers hide no skeleton.', 'Offer "An invertebrate, it is light with feathers" next to the right answer and ask the question again in a new context.', 'Look at the bones of a cooked chicken: the backbone is there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE.M_VR_HARD_BODY_RULE', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE', 'Uses a hard or soft body as the rule: a soft slug is an invertebrate, so a soft frog must be too.', '{"question":"A frog feels soft and wet. Is it a vertebrate?","wrong_answer":"No, it is soft so it has no backbone","correct_answer":"Yes, it has a backbone inside"}'::jsonb, 'Judges by how the outside feels instead of what is inside.', 'Offer "No, it is soft so it has no backbone" next to the right answer and ask the question again in a new context.', 'Feel along your own back: soft skin outside, a backbone inside. A frog is the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS.M_DP_WINDPIPE', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS', 'Mixes up the food pipe (oesophagus) with the windpipe.', '{"question":"Which tube carries food from the mouth to the stomach?","wrong_answer":"The windpipe","correct_answer":"The oesophagus (food pipe)"}'::jsonb, 'The child links "pipe in the neck" with food and air together.', 'Offer "The windpipe" next to the right answer and ask the question again in a new context.', 'Say the food pipe is for food and the windpipe is for air to the lungs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS.M_DP_STOMACH_ALL', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS', 'Thinks the stomach does all the digesting and takes in all the food.', '{"question":"Where does most digested food go into the blood?","wrong_answer":"The stomach","correct_answer":"The small intestine"}'::jsonb, 'The child knows the stomach is the "food bag" and nothing more.', 'Offer "The stomach" next to the right answer and ask the question again in a new context.', 'Say the stomach churns the food and the small intestine takes the good parts into the blood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS.M_DP_LARGE_INTESTINE_FOOD', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS', 'Thinks the large intestine takes in food (rather than water) or makes the food.', '{"question":"What does the large intestine take in from the leftover food?","wrong_answer":"Most of the food","correct_answer":"Water"}'::jsonb, 'The child expects the biggest tube to do the biggest job on food.', 'Offer "Most of the food" next to the right answer and ask the question again in a new context.', 'Say that the small intestine takes the food and the large intestine takes water and leaves the waste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER.M_DO_LARGE_BEFORE_SMALL', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER', 'Puts the large intestine before the small intestine.', '{"question":"Which comes first after the stomach?","wrong_answer":"The large intestine","correct_answer":"The small intestine"}'::jsonb, 'The child follows the words large then small.', 'Offer "The large intestine" next to the right answer and ask the question again in a new context.', 'Trace the path with a finger on a body chart: stomach, long small intestine, then large intestine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER.M_DO_SMALL_IS_SHORT', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER', 'Thinks the small intestine is short (small in length).', '{"question":"Which part of the intestine is longer?","wrong_answer":"The small intestine is short","correct_answer":"The small intestine is longer (it is narrow, not short)"}'::jsonb, 'The child hears small as short.', 'Offer "The small intestine is short" next to the right answer and ask the question again in a new context.', 'Measure a long string and say it stands for the small intestine, about six metres in an adult. The large intestine is wider and about 1.5 metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER.M_DO_STOMACH_FIRST', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER', 'Thinks food goes straight from the mouth to the stomach (leaves out the oesophagus), or that the stomach is the last part.', '{"question":"Which part is the last in the path of food?","wrong_answer":"The stomach","correct_answer":"The anus"}'::jsonb, 'The child stops the path at the stomach, where the food seems to go.', 'Offer "The stomach" next to the right answer and ask the question again in a new context.', 'Count the six parts with a finger, mouth to anus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH.M_DH_ONLY_WASH_FOOD', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH', 'Thinks washing food is enough, so washing hands does not matter.', '{"question":"Wanjiru washes the mangoes but not her hands. Is this enough?","wrong_answer":"Yes, clean food is all that matters","correct_answer":"No, she should wash her hands with soap too"}'::jsonb, 'The child sees only the food as a source of germs.', 'Offer "Yes, clean food is all that matters" next to the right answer and ask the question again in a new context.', 'Look at dirty hands under a lens and then at clean ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH.M_DH_SODA_FOR_WATER', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH', 'Thinks soda or sweets can take the place of water and meals.', '{"question":"What should Baraka drink most of through the day?","wrong_answer":"Soda","correct_answer":"Clean water"}'::jsonb, 'The child has seen drinks as the same as water.', 'Offer "Soda" next to the right answer and ask the question again in a new context.', 'Compare how much sugar sits in a bottle of soda with a glass of water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH.M_DH_UNBOILED_WATER', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH', 'Thinks any clear water from a stream is safe to drink without boiling or treating.', '{"question":"Njeri finds clear water in a stream. What should she do before drinking it?","wrong_answer":"Drink it, it looks clean","correct_answer":"Boil it or treat it first"}'::jsonb, 'The child judges water by how it looks.', 'Offer "Drink it, it looks clean" next to the right answer and ask the question again in a new context.', 'Show that clear water can still carry germs we cannot see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS.M_DP_FOOD_TO_LEGS', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS', 'Thinks food goes straight down a tube into the legs or fills the whole body like a bag.', '{"question":"After you eat ugali, where does the food go first after you swallow?","wrong_answer":"Into the whole body, all the way to the legs","correct_answer":"Down the oesophagus into the stomach"}'::jsonb, 'Has felt food "go down" and pictures the body as one hollow bag.', 'Offer "Into the whole body, all the way to the legs" next to the right answer and ask the question again in a new context.', 'Trace the path on a body outline with a string: mouth, food pipe, stomach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER.M_DO_ANUS_BEFORE_LARGE', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_ORDER', 'Puts the anus straight after the small intestine and leaves out the large intestine.', '{"question":"Which part comes after the small intestine?","wrong_answer":"The anus","correct_answer":"The large intestine"}'::jsonb, 'Remembers the start and end and forgets the part that takes in water.', 'Offer "The anus" next to the right answer and ask the question again in a new context.', 'Lay out the rope model and walk it; stop at each part before the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH.M_DH_FIBRE_NOT_NEEDED', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_HEALTH', 'Thinks vegetables and fruit are not needed if a child eats enough ugali and meat.', '{"question":"Which meal helps food pass well through the gut?","wrong_answer":"Ugali and meat only","correct_answer":"Ugali, beans and sukuma wiki with a fruit"}'::jsonb, 'Thinks a full stomach is all that matters.', 'Offer "Ugali and meat only" next to the right answer and ask the question again in a new context.', 'Talk about constipation: roughage from vegetables and fruit helps waste move through.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT.M_SS_POWDER_LIQUID', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT', 'Thinks sand, sugar or flour are liquids because they pour.', '{"question":"Is sand a solid, a liquid or a gas?","wrong_answer":"A liquid, it pours","correct_answer":"A solid"}'::jsonb, 'The child sees pouring as the mark of a liquid.', 'Offer "A liquid, it pours" next to the right answer and ask the question again in a new context.', 'Look at one grain of sand with a lens: each grain keeps its own shape.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT.M_SS_AIR_NOTHING', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT', 'Thinks air is nothing, or that a gas is not matter because it cannot be seen.', '{"question":"Is air a solid, a liquid or a gas?","wrong_answer":"Air is nothing, so it is none of them","correct_answer":"A gas"}'::jsonb, 'The child cannot see or hold air.', 'Offer "Air is nothing, so it is none of them" next to the right answer and ask the question again in a new context.', 'Blow up a balloon and feel it fill: the air takes up room.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT.M_SS_SOFT_NOT_SOLID', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT', 'Thinks soft things (a sponge, ugali, clay) are liquids, or not solids.', '{"question":"Is a sponge a solid, a liquid or a gas?","wrong_answer":"A liquid, because it is soft","correct_answer":"A solid"}'::jsonb, 'The child treats hard as the mark of a solid.', 'Offer "A liquid, because it is soft" next to the right answer and ask the question again in a new context.', 'Squeeze a sponge: it changes shape but keeps its own shape and does not flow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES.M_SP_LIQUID_OWN_SHAPE', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES', 'Thinks a liquid has its own shape.', '{"question":"Water is poured from a tall glass into a wide basin. What happens to its shape?","wrong_answer":"It keeps the shape of the glass","correct_answer":"It takes the shape of the basin"}'::jsonb, 'The child has seen a water drop and thinks a liquid has a shape.', 'Offer "It keeps the shape of the glass" next to the right answer and ask the question again in a new context.', 'Pour the same water into three different containers and draw its shape each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES.M_SP_GAS_WEIGHTLESS', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES', 'Thinks a gas has no weight, or no mass, or does not take up room.', '{"question":"Which statement about air is true?","wrong_answer":"Air has no weight and takes no room","correct_answer":"Air takes up room and has weight"}'::jsonb, 'The child cannot feel air.', 'Offer "Air has no weight and takes no room" next to the right answer and ask the question again in a new context.', 'Weigh a balloon before and after you blow it up on a simple balance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES.M_SP_VOLUME_CHANGES', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES', 'Thinks the amount of a liquid changes when it is poured into a different container.', '{"question":"One litre of water is poured from a bottle into a wide basin. How much water is there now?","wrong_answer":"More, it looks bigger in the basin","correct_answer":"The same, one litre"}'::jsonb, 'The child judges the amount by how it looks.', 'Offer "More, it looks bigger in the basin" next to the right answer and ask the question again in a new context.', 'Pour back from the basin into the bottle and see it fill again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT.M_SS_STEAM_IS_SMOKE', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATES_SORT', 'Thinks the steam from a boiling kettle is smoke, not water as a gas.', '{"question":"What is coming out of a boiling kettle?","wrong_answer":"Smoke from the heat","correct_answer":"Water as a gas (water vapour); the cloud is tiny drops of water"}'::jsonb, 'Sees a white cloud and links it with fire and smoke.', 'Offer "Smoke from the heat" next to the right answer and ask the question again in a new context.', 'Hold a cold plate (teacher only) above the kettle: drops of water form on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES.M_SP_SOLID_CANNOT_CHANGE', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES', 'Thinks a solid can never change its shape, so clay or plasticine is not a solid.', '{"question":"A learner squeezes plasticine into a new shape. Is it still a solid?","wrong_answer":"No, a solid cannot change shape","correct_answer":"Yes: it keeps its new shape until a force changes it"}'::jsonb, 'Hears "a solid has a fixed shape" and takes it to mean it can never be changed.', 'Offer "No, a solid cannot change shape" next to the right answer and ask the question again in a new context.', 'Leave the plasticine on the table: it keeps its shape by itself; only your push changed it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY.M_WC_PLASTIC_ROTS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY', 'Thinks plastic and polythene rot in the soil like food scraps.', '{"question":"Is a plastic bag decomposable or non-decomposable?","wrong_answer":"Decomposable, it will rot in the soil","correct_answer":"Non-decomposable"}'::jsonb, 'The child sees old torn bags and thinks they are going.', 'Offer "Decomposable, it will rot in the soil" next to the right answer and ask the question again in a new context.', 'Bury a banana peel and a polythene bag and dig up after a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY.M_WC_RUST_IS_ROT', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY', 'Thinks a rusting tin or metal rots, so it is decomposable.', '{"question":"Is a tin can decomposable or non-decomposable?","wrong_answer":"Decomposable, it goes brown and rusts","correct_answer":"Non-decomposable"}'::jsonb, 'The child sees rust and treats it as rotting.', 'Offer "Decomposable, it goes brown and rusts" next to the right answer and ask the question again in a new context.', 'Say that a tin takes very many years to break up and does not give soil back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY.M_WC_BURY_DISAPPEARS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY', 'Thinks anything buried in the soil disappears (glass, plastic) or that all waste that burns is decomposable.', '{"question":"A glass bottle is buried. Will it rot away into the soil?","wrong_answer":"Yes, anything buried disappears","correct_answer":"No, glass does not rot"}'::jsonb, 'The child sees buried things leave sight and thinks they have gone.', 'Offer "Yes, anything buried disappears" next to the right answer and ask the question again in a new context.', 'Dig up a buried bottle after a month and see it is unchanged.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS.M_WD_POLYTHENE_HARMLESS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS', 'Thinks polythene is harmless to animals that eat it.', '{"question":"A cow eats polythene bags thrown on the roadside. What can happen?","wrong_answer":"Nothing, the cow will digest it","correct_answer":"The cow can choke or fall sick and die"}'::jsonb, 'The child thinks animals can digest anything they eat.', 'Offer "Nothing, the cow will digest it" next to the right answer and ask the question again in a new context.', 'Tell the story of a cow whose stomach was found full of polythene.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS.M_WD_BURNING_SAFE', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS', 'Thinks burning waste has no danger.', '{"question":"Is there any danger in burning plastic waste?","wrong_answer":"No, the fire destroys the waste","correct_answer":"Yes, the smoke is harmful to breathe and pollutes the air"}'::jsonb, 'The child sees the heap disappear and thinks the problem is gone.', 'Offer "No, the fire destroys the waste" next to the right answer and ask the question again in a new context.', 'Notice the black smoke and the smell when plastic burns and who breathes it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS.M_WD_ONLY_SMELL', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS', 'Thinks the only trouble with a heap of waste is the smell.', '{"question":"Besides the smell, what can a heap of rotting waste cause?","wrong_answer":"Nothing more","correct_answer":"Diseases, as flies and rats breed in it"}'::jsonb, 'The child sees waste as unpleasant but not harmful.', 'Offer "Nothing more" next to the right answer and ask the question again in a new context.', 'Say that flies from the heap land on food and carry germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE.M_WM_BURN_ALL', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE', 'Thinks burning is the right way to get rid of all waste.', '{"question":"What is the best way to manage plastic bottles at school?","wrong_answer":"Burn them","correct_answer":"Collect them for recycling"}'::jsonb, 'The child sees burning as the quickest and cleanest way.', 'Offer "Burn them" next to the right answer and ask the question again in a new context.', 'List waste that is better reused or recycled, and note the smoke from burning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE.M_WM_DUMP_RIVER', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE', 'Thinks the river will carry waste away, so dumping in a river is fine.', '{"question":"Where should a family put household rubbish?","wrong_answer":"In the river, it will be carried away","correct_answer":"In a bin or collection point"}'::jsonb, 'The child thinks a river takes things to nowhere.', 'Offer "In the river, it will be carried away" next to the right answer and ask the question again in a new context.', 'Follow a river on a map and see it flows to a place where people live and fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE.M_WM_COMPOST_PLASTIC', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE', 'Thinks all waste can go in the compost pit, including plastic.', '{"question":"Which waste can go into the compost pit?","wrong_answer":"Vegetable peels and plastic bags","correct_answer":"Vegetable peels and dry leaves"}'::jsonb, 'The child sees the pit as a place for all waste.', 'Offer "Vegetable peels and plastic bags" next to the right answer and ask the question again in a new context.', 'Look at a compost heap: peels turn to soil, plastic stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY.M_WC_PAPER_NEVER_ROTS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY', 'Thinks paper is non-decomposable because it is made in a factory.', '{"question":"Is an old newspaper decomposable?","wrong_answer":"No, it is made in a factory","correct_answer":"Yes: paper is made from wood and rots in damp soil"}'::jsonb, 'Sorts by "natural or factory-made" instead of "rots or not".', 'Offer "No, it is made in a factory" next to the right answer and ask the question again in a new context.', 'Bury a piece of newspaper and a polythene bag; dig up after four weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS.M_WD_FAR_AWAY_NO_HARM', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_DANGERS', 'Thinks waste dumped far from home harms nobody.', '{"question":"A family throws plastic bags into a valley far from houses. Is there any danger?","wrong_answer":"No, nobody lives there","correct_answer":"Yes: animals eat them, rain washes them into rivers and drains get blocked"}'::jsonb, 'Thinks danger only means danger to people nearby.', 'Offer "No, nobody lives there" next to the right answer and ask the question again in a new context.', 'Follow the bag: wind and rain carry it to rivers, farms and the lake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE.M_WM_REUSE_DIRTY', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_MANAGE', 'Thinks reusing waste means using any container again, even a chemical or pesticide tin for food or water.', '{"question":"Which is a safe way to reuse a container?","wrong_answer":"Use an old pesticide tin to store drinking water","correct_answer":"Use a clean plastic bottle as a plant pot"}'::jsonb, 'Knows reuse is good but not that some containers stay poisonous.', 'Offer "Use an old pesticide tin to store drinking water" next to the right answer and ask the question again in a new context.', 'Read the danger sign on a pesticide tin with the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING.M_CM_STORE_ALL', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING', 'Thinks conserving water means storing as much as possible and never using it.', '{"question":"What does it mean to conserve water?","wrong_answer":"To store a lot and not use it","correct_answer":"To use it wisely and not waste it"}'::jsonb, 'The child hears save and thinks keep away.', 'Offer "To store a lot and not use it" next to the right answer and ask the question again in a new context.', 'Contrast a family that uses water wisely with one that wastes some.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING.M_CM_WATER_NEVER_ENDS', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING', 'Thinks water never runs out, because rain always fills the rivers.', '{"question":"Why must we conserve water?","wrong_answer":"Because water never runs out, so it does not matter","correct_answer":"Because clean water is not always enough"}'::jsonb, 'The child lives where water is always near.', 'Offer "Because water never runs out, so it does not matter" next to the right answer and ask the question again in a new context.', 'Talk about dry seasons when the river or the tank dries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING.M_CM_ONLY_CLEAN_DRINKING', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING', 'Thinks conserving water is only about keeping drinking water clean.', '{"question":"Which is an example of conserving water?","wrong_answer":"Boiling water for drinking only","correct_answer":"Closing a tap after use"}'::jsonb, 'The child mixes up conserving with making water safe.', 'Offer "Boiling water for drinking only" next to the right answer and ask the question again in a new context.', 'Sort actions into saving water and cleaning water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS.M_CMT_TAP_RUNS', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS', 'Thinks leaving the tap running while soaping hands or brushing teeth is fine.', '{"question":"Amina brushes her teeth. What should she do with the tap?","wrong_answer":"Leave it running","correct_answer":"Close it while she brushes"}'::jsonb, 'The child sees water as plentiful from a tap.', 'Offer "Leave it running" next to the right answer and ask the question again in a new context.', 'Measure water used when the tap is closed and when it runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS.M_CMT_HOSE_BETTER', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS', 'Thinks a hose or a running tap is a quicker, better way to water or wash.', '{"question":"How should a school water the vegetable garden?","wrong_answer":"With a running hose to be quick","correct_answer":"With a watering can, in the cool evening"}'::jsonb, 'The child links quickness with good use.', 'Offer "With a running hose to be quick" next to the right answer and ask the question again in a new context.', 'Time the work with a watering can and with a hose and compare how much water is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS.M_CMT_NO_RAINWATER', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS', 'Thinks rainwater is useless or must run away into the drain.', '{"question":"What can a school do with rain that falls on the roof?","wrong_answer":"Let it run away into the drain","correct_answer":"Collect it in a tank and use it"}'::jsonb, 'The child sees rain as only a nuisance.', 'Offer "Let it run away into the drain" next to the right answer and ask the question again in a new context.', 'Show a gutter and tank at school or at a neighbour''s house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE.M_CI_ONLY_BILL', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE', 'Thinks the only reason to save water is to pay a smaller bill.', '{"question":"Why is it important to save water?","wrong_answer":"Only to pay a smaller bill","correct_answer":"So there is enough for people, animals and plants, now and later"}'::jsonb, 'The child links saving with money only.', 'Offer "Only to pay a smaller bill" next to the right answer and ask the question again in a new context.', 'Ask a family who fetches water from far how they feel about wasted water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE.M_CI_ONLY_PEOPLE', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE', 'Thinks only people need water, not animals and plants.', '{"question":"Who needs water?","wrong_answer":"Only people","correct_answer":"People, animals and plants"}'::jsonb, 'The child links water with drinking and washing.', 'Offer "Only people" next to the right answer and ask the question again in a new context.', 'List what a farm needs water for: people, cattle, vegetables.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE.M_CI_RAIN_ENOUGH', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE', 'Thinks there is always enough water because of the rains.', '{"question":"What can happen in a long dry season?","wrong_answer":"Nothing, there is always enough water","correct_answer":"Rivers and wells can dry up and water becomes hard to find"}'::jsonb, 'The child has seen water in the rainy season only.', 'Offer "Nothing, there is always enough water" next to the right answer and ask the question again in a new context.', 'Recall the last dry season and how far people walked for water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING.M_CM_ONLY_WHEN_SHORT', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_MEANING', 'Thinks water needs saving only during a drought, not when there is plenty.', '{"question":"When should a family conserve water?","wrong_answer":"Only when there is a drought","correct_answer":"All the time, in the rains and in the dry season"}'::jsonb, 'Links saving only with shortage they have felt.', 'Offer "Only when there is a drought" next to the right answer and ask the question again in a new context.', 'Show that water saved in the rainy season (in tanks) is what lasts into the dry season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS.M_CMT_REUSE_DIRTY_DRINK', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_METHODS', 'Thinks used washing water can be reused for drinking or cooking.', '{"question":"Water used to wash clothes can be reused to","wrong_answer":"make tea","correct_answer":"water the flowers or flush a toilet"}'::jsonb, 'Knows reuse saves water but not which uses are safe.', 'Offer "make tea" next to the right answer and ask the question again in a new context.', 'Sort uses: drinking and cooking need clean water; plants and floors can take used water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE.M_CI_TAP_WATER_ENDLESS', 'SCIE.G4.MATTER.WATER_CONSERVATION.CONSERVE_IMPORTANCE', 'Thinks water from a tap comes from the pipe itself, so it never runs out.', '{"question":"Where does the water in the school tap come from?","wrong_answer":"From the pipe; pipes make water","correct_answer":"From a river, a borehole, a dam or a tank that can run dry"}'::jsonb, 'Has only seen the tap, not the source behind it.', 'Offer "From the pipe; pipes make water" next to the right answer and ask the question again in a new context.', 'Draw the path from a river or borehole to a tank to the tap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES.M_FT_PUSH_PULL_MIX', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES', 'Mixes up push and pull (calls opening a drawer a push, or kicking a pull).', '{"question":"A learner opens a drawer by holding the handle and moving it towards her. Is this a push or a pull?","wrong_answer":"A push","correct_answer":"A pull"}'::jsonb, 'The child thinks every action with force is a push.', 'Offer "A push" next to the right answer and ask the question again in a new context.', 'Do both with a real drawer and say which way the hand moves compared with the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES.M_FT_MAGNET_ALL', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES', 'Thinks a magnet attracts all metals (aluminium, copper, coins).', '{"question":"Which of these will a magnet pick up?","wrong_answer":"An aluminium spoon","correct_answer":"An iron nail"}'::jsonb, 'The child thinks magnetism is a property of every shiny metal.', 'Offer "An aluminium spoon" next to the right answer and ask the question again in a new context.', 'Test a spoon, a copper wire and an iron nail with a magnet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES.M_FT_GRAVITY_ONLY_FALLING', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES', 'Thinks gravity acts only on things that are falling.', '{"question":"A book is resting on a table. Is gravity acting on it?","wrong_answer":"No, it is not falling","correct_answer":"Yes, gravity is pulling it down and the table holds it up"}'::jsonb, 'The child thinks forces work only on moving things.', 'Offer "No, it is not falling" next to the right answer and ask the question again in a new context.', 'Hold a book in your hand and feel it press down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS.M_FE_ONLY_START', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS', 'Thinks a force can only start a movement and cannot stop one or change its direction.', '{"question":"A goalkeeper catches a fast ball. What did the force do?","wrong_answer":"It started the ball moving","correct_answer":"It stopped the ball"}'::jsonb, 'The child sees forces as only pushes that start things.', 'Offer "It started the ball moving" next to the right answer and ask the question again in a new context.', 'Roll a ball and stop it with the hand, then turn it with a stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS.M_FE_SHAPE_NOT_EFFECT', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS', 'Does not count a change of shape as an effect of a force.', '{"question":"A girl squeezes a lump of clay and it becomes flat. What did the force do?","wrong_answer":"Nothing, it only moved the clay","correct_answer":"It changed the shape of the clay"}'::jsonb, 'The child thinks forces only move things.', 'Offer "Nothing, it only moved the clay" next to the right answer and ask the question again in a new context.', 'Squeeze clay, a sponge and a rubber band and say what changed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS.M_FE_MOTION_NEEDS_FORCE', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS', 'Thinks a moving ball must still be pushed all the time to keep moving.', '{"question":"A ball rolls on the pitch after a kick. Why does it finally stop?","wrong_answer":"The push is used up","correct_answer":"Friction with the ground slows it down"}'::jsonb, 'The child thinks motion needs a force to continue.', 'Offer "The push is used up" next to the right answer and ask the question again in a new context.', 'Roll a ball over grass, over a road and over smooth floor, and compare how far it goes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES.M_FU_FRICTION_BAD_ONLY', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES', 'Thinks friction is only a problem and is never useful.', '{"question":"Why do bicycle brakes work?","wrong_answer":"Because of gravity","correct_answer":"Because of friction between the brake and the wheel"}'::jsonb, 'The child knows friction as what wears things out.', 'Offer "Because of gravity" next to the right answer and ask the question again in a new context.', 'Try to walk on a wet, smooth floor and say why it is hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES.M_FU_GRAVITY_ONLY_PROBLEM', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES', 'Thinks gravity is only a nuisance or only works on big things.', '{"question":"How does gravity help us?","wrong_answer":"It does not help us","correct_answer":"It makes rain fall and keeps things on the ground"}'::jsonb, 'The child knows gravity as what makes things fall and break.', 'Offer "It does not help us" next to the right answer and ask the question again in a new context.', 'Say what would happen to our water and cups if there were no gravity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES.M_FU_NOT_EVERYDAY', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES', 'Thinks only strong pushing and pulling uses force (carrying a box), not small tasks (writing, walking).', '{"question":"Which of these uses a force?","wrong_answer":"Only lifting a heavy sack","correct_answer":"Lifting a sack and also writing with a pencil"}'::jsonb, 'The child thinks only hard work uses force.', 'Offer "Only lifting a heavy sack" next to the right answer and ask the question again in a new context.', 'Press your hand on the desk and say which small tasks use a push or a pull.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES.M_FT_FORCE_IS_LIVING', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_TYPES', 'Thinks only living things can push or pull, so a magnet or the Earth cannot exert a force.', '{"question":"Can a magnet pull a pin without anyone touching it?","wrong_answer":"No, only people and animals can pull","correct_answer":"Yes, magnetic force pulls the pin"}'::jsonb, 'Has only met forces made by muscles.', 'Offer "No, only people and animals can pull" next to the right answer and ask the question again in a new context.', 'Hold a magnet near pins on a table: they move with no hand touching them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS.M_FE_STOPPED_NO_FORCE', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS', 'Thinks a ball that slows and stops by itself had no force acting on it.', '{"question":"A ball rolled on grass slows down and stops. Why?","wrong_answer":"Nothing made it stop; balls just stop","correct_answer":"Friction from the grass acted on it and stopped it"}'::jsonb, 'Does not see friction as a force because nothing visible pushes.', 'Offer "Nothing made it stop; balls just stop" next to the right answer and ask the question again in a new context.', 'Roll the ball on grass and on smooth cement: it rolls further where friction is less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES.M_FU_MORE_FORCE_ALWAYS_BETTER', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_USES', 'Thinks using more force is always better, for example pressing hard when writing or kicking hard when passing.', '{"question":"A learner presses very hard when writing with a pencil. What happens?","wrong_answer":"The writing is better","correct_answer":"The pencil point breaks or the paper tears"}'::jsonb, 'Thinks force is good, so more of it must be better.', 'Offer "The writing is better" next to the right answer and ask the question again in a new context.', 'Try writing gently and very hard: compare the paper and the pencil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES.M_LS_MOON_SOURCE', 'SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES', 'Thinks the Moon is a source of light.', '{"question":"Which of these gives out its own light?","wrong_answer":"The Moon","correct_answer":"The Sun"}'::jsonb, 'The child sees the Moon shining at night.', 'Offer "The Moon" next to the right answer and ask the question again in a new context.', 'Shine a torch on a mirror and look: the mirror lights up but is not a source.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES.M_LS_SHINY_SOURCE', 'SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES', 'Thinks shiny things (mirror, glass, a tin roof) are sources of light.', '{"question":"Which of these is a source of light?","wrong_answer":"A shiny tin roof in the sun","correct_answer":"A burning candle"}'::jsonb, 'The child links shiny with giving light.', 'Offer "A shiny tin roof in the sun" next to the right answer and ask the question again in a new context.', 'Cover the torch: the mirror goes dark. Cover a candle: the light stays with the flame.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES.M_LS_NATURAL_ONLY_SKY', 'SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES', 'Thinks natural sources are only in the sky (Sun, stars) and leaves out lightning and fireflies.', '{"question":"Which of these is a natural source of light?","wrong_answer":"An electric bulb","correct_answer":"A firefly"}'::jsonb, 'The child thinks only big things in the sky give light.', 'Offer "An electric bulb" next to the right answer and ask the question again in a new context.', 'Say which living things make light on a dark night.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING.M_HL_WINDOW_ONLY_AIR', 'SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING', 'Thinks windows are only for air and not a way of lighting a house.', '{"question":"How does a window help a classroom in the day?","wrong_answer":"It only lets in air","correct_answer":"It lets in light and air"}'::jsonb, 'The child thinks light comes only from bulbs.', 'Offer "It only lets in air" next to the right answer and ask the question again in a new context.', 'Close the shutters in a classroom and say what changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING.M_HL_DARK_WALLS', 'SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING', 'Thinks dark walls make a room brighter.', '{"question":"Which walls make a small room brighter?","wrong_answer":"Dark brown walls","correct_answer":"Light-coloured walls, like white"}'::jsonb, 'The child thinks dark means strong.', 'Offer "Dark brown walls" next to the right answer and ask the question again in a new context.', 'Compare a dark corner of a room and a white wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING.M_HL_CANDLE_LEFT', 'SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING', 'Thinks a lit candle or paraffin lamp can be left alone while the family sleeps.', '{"question":"A family goes to sleep. What should they do with the lit candle?","wrong_answer":"Leave it burning near the curtain","correct_answer":"Put it out before sleeping"}'::jsonb, 'The child has not thought about fire risks.', 'Offer "Leave it burning near the curtain" next to the right answer and ask the question again in a new context.', 'Tell the story of a house fire from a candle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_USES.M_LU_EYES_SEND', 'SCIE.G4.FORCE_.LIGHT.LIGHT_USES', 'Thinks we see because light comes out of our eyes.', '{"question":"How do we see a book?","wrong_answer":"Light comes out of our eyes and lands on it","correct_answer":"Light from a source bounces off the book into our eyes"}'::jsonb, 'The child thinks looking is an act we do to the thing.', 'Offer "Light comes out of our eyes and lands on it" next to the right answer and ask the question again in a new context.', 'Sit in a dark room with a book and say why you cannot see it until the lamp is on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_USES.M_LU_PLANT_SOIL_FOOD', 'SCIE.G4.FORCE_.LIGHT.LIGHT_USES', 'Thinks plants get all their food from the soil and do not need light.', '{"question":"Why do plants need light?","wrong_answer":"They do not need light, only soil","correct_answer":"To make their food"}'::jsonb, 'The child thinks the soil is the plant''s food.', 'Offer "They do not need light, only soil" next to the right answer and ask the question again in a new context.', 'Grow one seedling in the dark and one in the light and compare after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_USES.M_LU_ONLY_SEE', 'SCIE.G4.FORCE_.LIGHT.LIGHT_USES', 'Thinks the only use of light is to see.', '{"question":"What do traffic lights use light for?","wrong_answer":"To see in the dark","correct_answer":"To send signals to drivers"}'::jsonb, 'The child thinks light is only a way of seeing.', 'Offer "To see in the dark" next to the right answer and ask the question again in a new context.', 'List other uses: signals, solar power, plants, drying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES.M_LS_ARTIFICIAL_NATURAL_MIX', 'SCIE.G4.FORCE_.LIGHT.LIGHT_SOURCES', 'Calls a candle or a fire a natural source because it has a real flame.', '{"question":"Is a candle a natural or an artificial source of light?","wrong_answer":"Natural, because it has a real flame","correct_answer":"Artificial: people make and light it"}'::jsonb, 'Sorts by "real fire" instead of "made by people or not".', 'Offer "Natural, because it has a real flame" next to the right answer and ask the question again in a new context.', 'Ask of each source: did a person make it or light it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING.M_HL_MORE_BULBS_ONLY', 'SCIE.G4.FORCE_.LIGHT.HOUSE_LIGHTING', 'Thinks the only way to light a house better is more bulbs, not windows, light walls or skylights.', '{"question":"How can a dark kitchen be made brighter in the day without using electricity?","wrong_answer":"Put in more bulbs","correct_answer":"Add a window or a clear roof sheet, or paint the walls a light colour"}'::jsonb, 'Thinks lighting means artificial lights only.', 'Offer "Put in more bulbs" next to the right answer and ask the question again in a new context.', 'Compare the classroom with curtains open and closed, lights off.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.LIGHT.LIGHT_USES.M_LU_DARK_SEE_A_LITTLE', 'SCIE.G4.FORCE_.LIGHT.LIGHT_USES', 'Thinks eyes get used to total darkness and can see a little with no light at all.', '{"question":"In a room with no light at all, can you see your book after waiting a long time?","wrong_answer":"Yes, your eyes get used to it","correct_answer":"No: with no light at all, nothing can be seen"}'::jsonb, 'Has only been in rooms with a little light from a gap.', 'Offer "Yes, your eyes get used to it" next to the right answer and ask the question again in a new context.', 'Close a shoebox with a picture inside and look through a pinhole covered with a finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SOURCES.M_HS_SUN_ONLY', 'SCIE.G4.FORCE_.HEAT.HEAT_SOURCES', 'Thinks the Sun is the only source of heat.', '{"question":"Which of these is a source of heat?","wrong_answer":"Only the Sun","correct_answer":"The Sun and a charcoal fire"}'::jsonb, 'The child thinks heat comes only from the sky.', 'Offer "Only the Sun" next to the right answer and ask the question again in a new context.', 'List what we use for heat in the kitchen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SOURCES.M_HS_HOT_OBJECT_SOURCE', 'SCIE.G4.FORCE_.HEAT.HEAT_SOURCES', 'Thinks a hot thing (a cup of tea, a hot stone) is a source of heat.', '{"question":"Which is a source of heat?","wrong_answer":"A hot stone in the sun","correct_answer":"A burning charcoal stove"}'::jsonb, 'The child thinks anything hot makes heat.', 'Offer "A hot stone in the sun" next to the right answer and ask the question again in a new context.', 'Ask what made the stone hot: the Sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SOURCES.M_HS_RUBBING_NOT_HEAT', 'SCIE.G4.FORCE_.HEAT.HEAT_SOURCES', 'Does not think rubbing makes heat (friction as a source).', '{"question":"Njoroge rubs his hands together on a cold morning. What happens?","wrong_answer":"Nothing, rubbing does not make heat","correct_answer":"His hands get warm because of friction"}'::jsonb, 'The child thinks heat comes only from fires.', 'Offer "Nothing, rubbing does not make heat" next to the right answer and ask the question again in a new context.', 'Rub the palms for 20 seconds and say how they feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES.M_HU_BOIL_NOT_SAFE', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'Thinks boiling water does not make it safer to drink.', '{"question":"Why do we boil drinking water?","wrong_answer":"To make it taste nice","correct_answer":"To kill germs and make it safe"}'::jsonb, 'The child sees boiling as only for making tea.', 'Offer "To make it taste nice" next to the right answer and ask the question again in a new context.', 'Say that germs in water die when it boils.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES.M_HU_DRY_IN_SHADE', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'Thinks clothes dry best in the shade or in the rain.', '{"question":"Where do wet clothes dry fastest?","wrong_answer":"In the shade","correct_answer":"In the sun and wind"}'::jsonb, 'The child links drying with not getting hot.', 'Offer "In the shade" next to the right answer and ask the question again in a new context.', 'Hang two cloths, one in the sun and one in the shade, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES.M_HU_ONLY_COOKING', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'Thinks the only use of heat is to cook.', '{"question":"Which of these is also a use of heat?","wrong_answer":"There is no other use, only cooking","correct_answer":"Drying grain and warming a house"}'::jsonb, 'The child links heat with the kitchen.', 'Offer "There is no other use, only cooking" next to the right answer and ask the question again in a new context.', 'List five jobs done with heat at home and on the farm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY.M_SF_BUTTER_ON_BURN', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'Thinks butter, oil or ash should be put on a burn.', '{"question":"A child burns her hand. What should be done first?","wrong_answer":"Rub butter on it","correct_answer":"Put the burn under cool running water"}'::jsonb, 'This is a common home custom.', 'Offer "Rub butter on it" next to the right answer and ask the question again in a new context.', 'Say that cool water takes the heat out of the skin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY.M_SF_REFILL_LIT', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'Thinks a lit stove or jiko can be refilled with paraffin or charcoal while burning.', '{"question":"A paraffin stove is nearly empty and still burning. What is the safe thing to do?","wrong_answer":"Pour more paraffin in at once","correct_answer":"Put it out, let it cool, then refill"}'::jsonb, 'The child wants to save time.', 'Offer "Pour more paraffin in at once" next to the right answer and ask the question again in a new context.', 'Say that paraffin catches fire from a flame.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY.M_SF_WET_CLOTH', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'Thinks a wet cloth is good for holding a hot pot.', '{"question":"What should you use to lift a hot pot?","wrong_answer":"A wet cloth","correct_answer":"A dry cloth or pot holder"}'::jsonb, 'The child thinks wet cools the pot.', 'Offer "A wet cloth" next to the right answer and ask the question again in a new context.', 'Say that steam from a wet cloth burns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SOURCES.M_HS_COLD_HAS_COLDNESS', 'SCIE.G4.FORCE_.HEAT.HEAT_SOURCES', 'Thinks a cold thing (ice, cold water) gives out "coldness" in the same way a fire gives out heat.', '{"question":"Ice in a cup makes your hand feel cold. Why?","wrong_answer":"The ice gives coldness to your hand","correct_answer":"Heat flows from your warm hand into the ice"}'::jsonb, 'Feels cold as something that moves, like heat does.', 'Offer "The ice gives coldness to your hand" next to the right answer and ask the question again in a new context.', 'Hold an ice cube: it melts because heat from your hand goes into it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_USES.M_HU_HEAT_ONLY_FIRE', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'Thinks the Sun''s heat cannot be used for work, only heat from a fire.', '{"question":"How can a family dry beans after harvest without a fire?","wrong_answer":"They cannot; drying needs a fire","correct_answer":"Spread them in the sun on a mat"}'::jsonb, 'Links "using heat" only with fires and stoves.', 'Offer "They cannot; drying needs a fire" next to the right answer and ask the question again in a new context.', 'Dry two wet cloths, one in the sun, one in a shaded room: compare after an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G4.FORCE_.HEAT.HEAT_SAFETY.M_SF_WATER_ON_OIL_FIRE', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'Thinks water is the right thing to throw on a burning pan of oil.', '{"question":"A pan of cooking oil catches fire. What should an adult do?","wrong_answer":"Throw water on it","correct_answer":"Turn off the heat and cover the pan with a lid or a damp cloth"}'::jsonb, 'Knows water puts out wood fires and uses it for every fire.', 'Offer "Throw water on it" next to the right answer and ask the question again in a new context.', 'Explain: water makes burning oil splash and spread. Covering stops the air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
